contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint256 reqID) public {
        // The test contract is not the owner recorded in the clone's immutable args,
        // so any rescind attempt from here must be rejected.
        address ownerBefore = c.owner();
        require(ownerBefore != address(this));
        bool reverted;
        try c.rescindRequest(reqID) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assert(reverted);
    }
    receive() external payable {}
}

