contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 loanID, address to) public {
        // Precondition: the loan identified by loanID has no lender set.
        require(c.getLoan(loanID).lender == address(0));

        bool reverted;
        try c.approveTransfer(to, loanID) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Rule: only the current lender of an existing loan may approve a
        // transfer; when no lender exists (zero address), the call must revert.
        assert(reverted);
    }

    receive() external payable {}
}

