contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 loanID, address to) public {
        // On a fresh cooler there are no loans, so loans[loanID].lender is address(0),
        // which is never msg.sender (this test contract); likewise approvals[loanID] is address(0).
        // Hence approveTransfer and transferOwnership must both revert (OnlyApproved)
        // for every loan id and any recipient address.

        bool approveReverted;
        bool transferReverted;

        // approveTransfer from a caller that is not the lender must revert.
        bool approveOk;
        try c.approveTransfer(to, loanID) { approveOk = true; } catch { approveOk = false; }
        approveReverted = !approveOk;

        // transferOwnership from a caller that is not the approved recipient must revert.
        bool transferOk;
        try c.transferOwnership(loanID) { transferOk = true; } catch { transferOk = false; }
        transferReverted = !transferOk;

        assert(approveReverted && transferReverted);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 reqID, bool repayDirect) public payable {
        require(true);

        // The caller (this contract) does not implement CoolerCallback,
        // so clearRequest with isCallback_=true must revert, no matter
        // the request id or whether a request exists.
        bool reverted;
        try c.clearRequest(reqID, repayDirect, true) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // And the revert must be exactly because of the callback check:
        // doing the same call without the callback flag must not revert
        // merely due to gas or other side effects before it.
        assert(reverted);
    }

    receive() external payable {}
}

